 subtopic,'pcac-admin-challenge-'||lpad(n::text,2,'0'),
 'pcac-2026-admin-challenge-'||lpad(n::text,2,'0'),
 jsonb_build_object('kind','didactic_original','authored',true,'target_exam','PC-AC 2026 — Oficial Investigador de Polícia','license_note','Questão autoral inédita; não é item oficial da IDECAN','not_official_exam',true,'source_board_style','IDECAN','reference_source_url','https://sead.ac.gov.br/wp-content/uploads/2026/11/Edital-no-001-PCAC-Edital-de-abertura-05-11-2026.pdf','source_material_slug',material_slug,'linked_study_material_slug',material_slug)
